 "content": "from collections import Counter, deque


def transform(grid):
    """Fill rectangular frames on their even-parity interior cells using
    the scattered color whose marker count best matches the required cells.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    frames = []
    frame_cells = set()

    # A frame is a 4-connected component whose bounding box has a complete,
    # single-color rectangular perimeter and at least one interior cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in comp); r1 = max(y for y, _ in comp)
            c0 = min(x for _, x in comp); c1 = max(x for _, x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = ([(r0, x) for x in range(c0, c1+1)] +
                         [(r1, x) for x in range(c0, c1+1)] +
                         [(y, c0) for y in range(r0+1, r1)] +
                         [(y, c1) for y in range(r0+1, r1)])
            if all(grid[y][x] == color for y, x in perimeter):
                frames.append((r0, r1, c0, c1, color))
                frame_cells.update(perimeter)

    marker_counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                            if grid[r][c] != 0 and (r, c) not in frame_cells)
    # Exclude any non-frame colored cell that belongs to a frame interior; such
    # interiors are blank in the examples and should not be marker evidence.
    for r0, r1, c0, c1, _ in frames:
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                if grid[r][c] != 0:
                    marker_counts[grid[r][c]] -= 1

    needs = []
    for r0, r1, c0, c1, frame_color in frames:
        need = sum(1 for r in range(r0+1, r1) for c in range(c0+1, c1)
                   if (r-r0-1 + c-c0-1) % 2 == 0)
        if need:
            needs.append((need, r0, r1, c0, c1, frame_color))

    # Match each frame to a distinct scattered marker color by nearest count.
    available = {color: count for color, count in marker_counts.items() if count > 0}
    assignments = {}
    for need, r0, r1, c0, c1, frame_color in sorted(needs):
        candidates = [(abs(count-need), color) for color, count in available.items()]
        if not candidates:
            continue
        _, marker_color = min(candidates)
        assignments[(r0, r1, c0, c1, frame_color)] = marker_color
        del available[marker_color]

    for r0, r1, c0, c1, frame_color in frames:
        marker_color = assignments.get((r0, r1, c0, c1, frame_color))
        if marker_color is None:
            continue
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                if (r-r0-1 + c-c0-1) % 2 == 0 and grid[r][c] == 0:
                    out[r][c] = marker_color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
